40	  private async _directoryEntries(directory: FileSystemDirectoryHandle): Promise<[string, FileSystemHandle][]> {
41	    // Firefox Xray wrappers expose only string-named WebIDL members, so the async
42	    // iterator has no Symbol.asyncIterator here ('directory.entries() is not
43	    // iterable') and `for await` cannot be used. Drive the iterator manually.
44	    const result: [string, FileSystemHandle][] = [];
45	    const iterator = directory.entries();
46	    while (true) {
47	      const entry = await iterator.next();
48	      if (entry.done)
49	        return result;
50	      result.push(entry.value);
51	    }
52	  }
