54	  private _isPlainObject(v: any) {
55	    const ctor = v?.constructor;
56	    if (this._isFirefox) {
57	      const constructorImpl = ctor?.toString() as string | undefined;
58	      if (constructorImpl?.startsWith('function Object() {') && constructorImpl?.includes('[native code]'))
59	        return true;
60	    }
61	    return ctor === Object;
62	  }
