64	  private _trySerialize(value: any): { trivial?: any, encoded?: any } {
65	    let trivial = true;
66	    const encoded = serializeAsCallArgument(value, v => {
67	      const isTrivial = (
68	        this._isPlainObject(v)
69	        || Array.isArray(v)
70	        || typeof v === 'string'
71	        || typeof v === 'number'
72	        || typeof v === 'boolean'
73	        || Object.is(v, null)
74	      );
75	
76	      if (!isTrivial)
77	        trivial = false;
78	
79	      return { fallThrough: v };
80	    });
81	    if (trivial)
82	      return { trivial: value };
83	    return { encoded };
84	  }
