86	  private async _collectDB(dbInfo: IDBDatabaseInfo) {
87	    if (!dbInfo.name)
88	      throw new Error('Database name is empty');
89	    if (!dbInfo.version)
90	      throw new Error('Database version is unset');
91	
92	    const db = await this._idbRequestToPromise(indexedDB.open(dbInfo.name));
93	    try {
94	      if (db.objectStoreNames.length === 0)
95	        return { name: dbInfo.name, version: dbInfo.version, stores: [] };
96	
97	      const transaction = db.transaction(db.objectStoreNames, 'readonly');
98	      const stores = await Promise.all([...db.objectStoreNames].map(async storeName => {
99	        const objectStore = transaction.objectStore(storeName);
100	
101	        const keys = await this._idbRequestToPromise(objectStore.getAllKeys());
102	        const records = await Promise.all(keys.map(async key => {
103	          const record: IndexedDBDatabase['stores'][0]['records'][0] = {};
104	
105	          if (objectStore.keyPath === null) {
106	            const { encoded, trivial } = this._trySerialize(key);
107	            if (trivial)
108	              record.key = trivial;
109	            else
110	              record.keyEncoded = encoded;
111	          }
112	
113	          const value = await this._idbRequestToPromise(objectStore.get(key));
114	          const { encoded, trivial } = this._trySerialize(value);
115	          if (trivial)
116	            record.value = trivial;
117	          else
118	            record.valueEncoded = encoded;
119	
120	          return record;
121	        }));
122	
123	        const indexes = [...objectStore.indexNames].map(indexName => {
124	          const index = objectStore.index(indexName);
125	          return {
126	            name: index.name,
127	            keyPath: typeof index.keyPath === 'string' ? index.keyPath : undefined,
128	            keyPathArray: Array.isArray(index.keyPath) ? index.keyPath : undefined,
129	            multiEntry: index.multiEntry,
130	            unique: index.unique,
131	          };
132	        });
133	
134	        return {
135	          name: storeName,
136	          records: records,
137	          indexes,
138	          autoIncrement: objectStore.autoIncrement,
139	          keyPath: typeof objectStore.keyPath === 'string' ? objectStore.keyPath : undefined,
140	          keyPathArray: Array.isArray(objectStore.keyPath) ? objectStore.keyPath : undefined,
141	        };
142	      }));
143	
144	      return {
145	        name: dbInfo.name,
146	        version: dbInfo.version,
147	        stores,
148	      };
149	    } finally {
150	      db.close();
151	    }
152	  }
