154	  private async _collectOPFS(root: FileSystemDirectoryHandle): Promise<OPFSEntry[]> {
155	    const collect = async (directory: FileSystemDirectoryHandle, parentPath: string): Promise<OPFSEntry[]> => {
156	      const entries = await this._directoryEntries(directory);
157	      entries.sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0);
158	
159	      const results = await Promise.all(entries.map(async ([name, handle]): Promise<OPFSEntry[]> => {
160	        const path = parentPath ? `${parentPath}/${name}` : name;
161	        if (handle.kind === 'directory')
162	          return [{ path, type: 'directory' }, ...await collect(handle as FileSystemDirectoryHandle, path)];
163	        const file = await (handle as FileSystemFileHandle).getFile();
164	        const base64 = typedArrayToBase64(new Uint8Array(await file.arrayBuffer()));
165	        return [{ path, type: 'file', base64 }];
166	      }));
167	      return results.flat();
168	    };
169	    return collect(root, '');
170	  }
