172	  async collect(record: { indexedDB: boolean, opfs: boolean }): Promise<SerializedStorage> {
173	    const localStorage = Object.keys(this._global.localStorage).map(name => ({ name, value: this._global.localStorage.getItem(name)! }));
174	    const result: SerializedStorage = { localStorage };
175	    if (record.indexedDB) {
176	      try {
177	        const databases = await this._global.indexedDB.databases();
178	        result.indexedDB = await Promise.all(databases.map(db => this._collectDB(db)));
179	      } catch (e) {
180	        throw new Error('Unable to serialize IndexedDB: ' + e.message);
181	      }
182	    }
183	    if (record.opfs) {
184	      try {
185	        result.opfs = await this._collectOPFS(await this._global.navigator.storage.getDirectory());
186	      } catch (e) {
187	        throw new Error('Unable to serialize OPFS: ' + e.message);
188	      }
189	    }
190	    return result;
191	  }
