193	  private async _restoreDB(dbInfo: IndexedDBDatabase) {
194	    const openRequest = this._global.indexedDB.open(dbInfo.name, dbInfo.version);
195	    openRequest.addEventListener('upgradeneeded', () => {
196	      const db = openRequest.result;
197	      for (const store of dbInfo.stores) {
198	        const objectStore = db.createObjectStore(store.name, { autoIncrement: store.autoIncrement, keyPath: store.keyPathArray ?? store.keyPath });
199	        for (const index of store.indexes)
200	          objectStore.createIndex(index.name, index.keyPathArray ?? index.keyPath!, { unique: index.unique, multiEntry: index.multiEntry });
201	      }
202	    });
203	
204	    // after `upgradeneeded` finishes, `success` event is fired.
205	    const db = await this._idbRequestToPromise(openRequest);
206	    try {
207	      if (db.objectStoreNames.length === 0)
208	        return;
209	      const transaction = db.transaction(db.objectStoreNames, 'readwrite');
210	      await Promise.all(dbInfo.stores.map(async store => {
211	        const objectStore = transaction.objectStore(store.name);
212	        await Promise.all(store.records.map(async record => {
213	          await this._idbRequestToPromise(
214	              objectStore.add(
215	                  record.value ?? parseEvaluationResultValue(record.valueEncoded),
216	                  record.key ?? parseEvaluationResultValue(record.keyEncoded),
217	              )
218	          );
219	        }));
220	      }));
221	    } finally {
222	      db.close();
223	    }
224	  }
